import AppKit
import SwiftUI

/// Receives raw Back buttons and native navigation swipes (including those
/// generated by mouse drivers) anywhere in this content's window.
struct MouseBackNavigation: NSViewRepresentable {
    let goBack: () -> Bool

    func makeNSView(context: Context) -> MouseBackMonitorView {
        let view = MouseBackMonitorView()
        view.goBack = goBack
        return view
    }

    func updateNSView(_ view: MouseBackMonitorView, context: Context) {
        view.goBack = goBack
    }

    static func dismantleNSView(_ view: MouseBackMonitorView, coordinator: ()) {
        view.stopMonitoring()
    }
}

@MainActor
final class MouseBackMonitorView: NSView {
    var goBack: () -> Bool = { false }
    private var monitor: Any?
    private var consumedMouseDown = false

    override func hitTest(_ point: NSPoint) -> NSView? { nil }

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        stopMonitoring()
        guard window != nil else { return }
        monitor = NSEvent.addLocalMonitorForEvents(matching: [.otherMouseDown, .otherMouseUp, .swipe]) { [weak self] event in
            guard let self else { return event }
            return self.handle(event)
        }
    }

    func stopMonitoring() {
        if let monitor { NSEvent.removeMonitor(monitor) }
        monitor = nil
        consumedMouseDown = false
    }

    func handle(_ event: NSEvent) -> NSEvent? {
        guard let window, window.attachedSheet == nil, NSApp.modalWindow == nil else { return event }
        // Driver-generated events can have no window. Only the key window may
        // handle those, so another SpaceLens window never navigates as well.
        let targetsWindow = event.window.map { $0 === window } ?? window.isKeyWindow
        guard targetsWindow else { return event }

        switch event.type {
        case .otherMouseDown:
            guard event.buttonNumber == 3 else { return event }
            consumedMouseDown = goBack()
            return consumedMouseDown ? nil : event
        case .otherMouseUp:
            guard event.buttonNumber == 3 else { return event }
            let consumed = consumedMouseDown
            consumedMouseDown = false
            return consumed ? nil : event
        case .swipe:
            // Native legacy swipe-left is Back, as emitted by Logi Options+.
            // deltaX is positive for this event, independent of scroll settings.
            guard event.deltaX > 0, abs(event.deltaX) > abs(event.deltaY) else { return event }
            return goBack() ? nil : event
        default:
            return event
        }
    }
}
